import logging
import time

import wrapt

from ..thread import KillableThread
from ..timeout import Timeout
from ute_common_util.ignore import ignore_exceptions
from .exception import ScannerExecutionTimeout, ScannerExecutionError, ScannerExecutionResultError


log = logging.getLogger("Manager")


class ExecutionManager(object):

    def run(self, timeout, method, *args, **kwargs):
        """Runs execution process.

        :param float timeout: Timeout for whole execution process.
        :param method: Method to execute.

        :return: Output from the execution.
        :rtype: string

        :raise: ScannerExecutionTimeout if result it is not available before timeout.
        :raise: ScannerExecutionError if execution finished with error code.
        :raise: ScannerExecutionResultError if result format is incorrect.
        """
        timeout = Timeout(timeout)
        worker = self._start_worker(method, *args, **kwargs)
        self._wait_for_worker(worker, timeout)
        self._terminate_worker(worker)
        self._check_timeout(timeout)
        self._check_result_format(worker.result)
        self._check_result_rc(worker.result)
        return worker.result.out

    def _start_worker(self, method, *args, **kwargs):
        worker = ExecutionWorker(method, *args, **kwargs)
        worker.daemon = True
        worker.start()
        return worker

    def _wait_for_worker(self, worker, timeout):
        while timeout.is_not_reached():
            if not worker.is_alive():
                break

    def _check_timeout(self, timeout):
        if timeout.is_reached():
            raise ScannerExecutionTimeout("Execution timeout occured")

    def _check_result_format(self, result):
        if not result.has_valid_format():
            raise ScannerExecutionResultError("Returned result is not supported. Supported are list/tuple with three or more values.")

    def _check_result_rc(self, result):
        if not result.has_valid_rc():
            raise ScannerExecutionError("NMAP application execution finished with error."
                                        "Please check if NMAP application is installed properly.", result.out, result.err)

    def _terminate_worker(self, worker):
        worker.terminate()


class ExecutionWorker(KillableThread):
    def __init__(self, method, *args, **kwargs):
        """
        :param method: Method to execute.
        """
        super(ExecutionWorker, self).__init__()
        self._method = method
        self._result = None
        self._args = args
        self._kwargs = kwargs

    @property
    @wrapt.synchronized
    def result(self):
        """Property to get worker result."""
        return self._result

    @result.setter
    @wrapt.synchronized
    def result(self, value):
        """Property to set worker result."""
        self._result = ExecutionResult(value)

    @ignore_exceptions([Exception], None, log.debug)
    def run(self):
        """Main execution body."""
        self.result = self._method(*self._args, **self._kwargs)


class ExecutionResult(object):
    def __init__(self, result):
        self._result = result

    def has_valid_format(self):
        """Method looks into result and decide if provided result is in supported format.

        Supported format is:
            * list or tuple
            * 3 or more entries
        """
        if isinstance(self._result, list) or isinstance(self._result, tuple):
            if len(self._result) >= 3:
                return True
        return False

    def has_valid_rc(self):
        """Method looks into result and decide if return code has a valid value."""
        return True if self.rc == 0 else False

    @property
    def out(self):
        """Returns output from the result."""
        return self._result[0]

    @property
    def err(self):
        """Returns errors from the result."""
        return self._result[1]

    @property
    def rc(self):
        """Returns return code from the result."""
        return self._result[2]
